package com.clearchoice;
import android.content.*;import org.json.*;import java.util.*;
public final class Profiles {
 public static final String[] SCOPES={"global","app","SHOP","PRODUCT","CART"};
 public static SharedPreferences prefs(Context c,String scope){return c.getSharedPreferences(scope.equals("global")?"studio":"studio_"+scope,0);}
 public static SharedPreferences effective(Context c,String screen){SharedPreferences p=prefs(c,screen);if(Arrays.asList(SCOPES).contains(screen)&&p.getBoolean("configured",false))return p;p=prefs(c,"app");return p.getBoolean("configured",false)?p:prefs(c,"global");}
 public static JSONObject validate(String json)throws JSONException{if(json.length()>16000)throw new JSONException("Profile exceeds size limit");JSONObject root=new JSONObject(json);if(root.optInt("schema")!=1||root.length()!=2)throw new JSONException("Unsupported profile schema");JSONObject all=root.getJSONObject("profiles");Iterator<String> scopes=all.keys();while(scopes.hasNext()){String scope=scopes.next();if(!Arrays.asList(SCOPES).contains(scope))throw new JSONException("Unsupported scope");JSONObject p=all.getJSONObject(scope);Iterator<String> keys=p.keys();while(keys.hasNext())if(!Arrays.asList("profile","spacing","text","compact","prompt").contains(keys.next()))throw new JSONException("Unsupported setting");if(!Arrays.asList("Balanced","Minimal","Accessible","Custom").contains(p.getString("profile")))throw new JSONException("Unknown preset");if(p.getInt("spacing")<0||p.getInt("spacing")>24||p.getInt("text")<0||p.getInt("text")>14||p.getString("prompt").length()>300)throw new JSONException("Setting outside range");p.getBoolean("compact");}return root;}
 public static String exportJson(Context c)throws JSONException{JSONObject all=new JSONObject();for(String scope:SCOPES){SharedPreferences p=prefs(c,scope);if(!scope.equals("global")&&!p.getBoolean("configured",false))continue;JSONObject v=new JSONObject();v.put("profile",p.getString("profile","Balanced"));v.put("spacing",p.getInt("spacing",8));v.put("text",p.getInt("text",4));v.put("compact",p.getBoolean("compact",false));v.put("prompt",p.getString("prompt",""));all.put(scope,v);}return new JSONObject().put("schema",1).put("profiles",all).toString(2);}
 public static void importJson(Context c,String json)throws JSONException{JSONObject all=validate(json).getJSONObject("profiles");Iterator<String> it=all.keys();while(it.hasNext()){String scope=it.next();JSONObject p=all.getJSONObject(scope);prefs(c,scope).edit().putBoolean("configured",true).putString("profile",p.getString("profile")).putInt("spacing",p.getInt("spacing")).putInt("text",p.getInt("text")).putBoolean("compact",p.getBoolean("compact")).putString("prompt",p.getString("prompt")).apply();}}
 private Profiles(){}
}
